<script setup lang="ts">import {onMounted,ref} from 'vue';import {useRouter} from 'vue-router';import {api,idr} from '../api';import {useCart,useSession} from '../stores';const cart=useCart(),session=useSession(),router=useRouter(),addresses=ref<any[]>([]),addressId=ref(''),error=ref(''),form=ref({recipientName:'',phone:'',addressLine:'',city:'',province:'',postalCode:'',isDefault:true});onMounted(async()=>{if(!session.user)return router.push('/login');await cart.load();addresses.value=await api('/addresses');addressId.value=addresses.value.find(a=>a.isDefault)?.id??addresses.value[0]?.id??''});async function saveAddress(){try{const address=await api<any>('/addresses',{method:'POST',body:JSON.stringify(form.value)});addresses.value.push(address);addressId.value=address.id}catch(e:any){error.value=e.message}}async function place(){try{const order=await api<any>('/checkout/orders',{method:'POST',body:JSON.stringify({addressId:addressId.value,idempotencyKey:crypto.randomUUID()})});await cart.load();router.push(`/account/orders?created=${order.id}`)}catch(e:any){error.value=e.message}}</script>
<template><main class="container page"><header class="page-title"><small>SECURE CHECKOUT</small><h1>One step closer.</h1></header><p v-if="error" class="notice">{{error}}</p><div class="checkout"><section><h2>Shipping address</h2><div v-if="addresses.length" class="address-list"><label v-for="a in addresses" :key="a.id"><input v-model="addressId" type="radio" :value="a.id"/><span><b>{{a.recipientName}}</b><br/>{{a.addressLine}}, {{a.city}}, {{a.province}} {{a.postalCode}}</span></label></div><form class="form-grid" @submit.prevent="saveAddress"><h3>Add a new address</h3><input v-model="form.recipientName" placeholder="Recipient name" required/><input v-model="form.phone" placeholder="Phone number" required/><input v-model="form.addressLine" class="full" placeholder="Full address" required/><input v-model="form.city" placeholder="City" required/><input v-model="form.province" placeholder="Province" required/><input v-model="form.postalCode" placeholder="Postal code" required/><button class="text-button">Save address</button></form></section><aside class="summary"><h2>Your order</h2><p v-for="i in cart.items"><span>{{i.product.name}} × {{i.quantity}}</span><b>{{idr(Number(i.product.price)*i.quantity)}}</b></p><hr/><p><span>Shipping</span><b>{{idr(25000)}}</b></p><p class="total"><span>Total</span><b>{{idr(cart.total+25000)}}</b></p><button class="button" :disabled="!addressId||!cart.items.length" @click="place">Place order</button><small>Payment is simulated in this demo.</small></aside></div></main></template>
